// ESTOQUE INICIAL DE HARLEYS E CHOPPERS COM LINKS DE IMAGENS REAIS
let estoque = [
  {
      codigo: 101,
          descricao: "Harley Davidson Custom Chopper 1600cc",
              quantidade: 3,
                  valor: 89900.00,
                      imagem: "https://images.unsplash.com/photo-1558981806-ec527fa84c39?w=600&auto=format&fit=crop"
                        },
                          {
                              codigo: 102,
                                  descricao: "Chopper Chrome Edition V-Twin Engine",
                                      quantidade: 2,
                                          valor: 74500.00,
                                              imagem: "https://images.unsplash.com/photo-1558981403-c5f9899a28bc?w=600&auto=format&fit=crop"
                                                },
                                                  {
                                                      codigo: 103,
                                                          descricao: "Dark Custom Bobber Long Fork 1200cc",
                                                              quantidade: 5,
                                                                  valor: 62000.00,
                                                                      imagem: "https://images.unsplash.com/photo-1558980862-23f497a9f81a?w=600&auto=format&fit=crop"
                                                                        },
                                                                          {
                                                                              codigo: 104,
                                                                                  descricao: "Vintage Flame Custom Chopper Cruiser",
                                                                                      quantidade: 1,
                                                                                          valor: 98000.00,
                                                                                              imagem: "https://images.unsplash.com/photo-1558981359-219d6364c9c8?w=600&auto=format&fit=crop"
                                                                                                }
                                                                                                ];

                                                                                                // ARRAY DO CARRINHO DE COMPRAS
                                                                                                let carrinho = [];

                                                                                                // ELEMENTOS DO DOM
                                                                                                const form = document.getElementById('form-produto');
                                                                                                const tabelaEstoque = document.getElementById('tabela-estoque');
                                                                                                const gridProdutos = document.getElementById('grid-produtos');
                                                                                                const carrinhoQtd = document.getElementById('carrinho-qtd');
                                                                                                const modalCarrinho = document.getElementById('modal-carrinho');
                                                                                                const itensCarrinhoContainer = document.getElementById('itens-carrinho');
                                                                                                const cartTotalValor = document.getElementById('cart-total-valor');

                                                                                                function atualizarInterface() {
                                                                                                  renderizarCatalogo(estoque);
                                                                                                    renderizarTabela(estoque);
                                                                                                      atualizarCarrinhoModal();
                                                                                                      }

                                                                                                      // 1. RENDERIZAR VITRINE DA LOJA
                                                                                                      function renderizarCatalogo(lista) {
                                                                                                        gridProdutos.innerHTML = '';

                                                                                                          if (lista.length === 0) {
                                                                                                              gridProdutos.innerHTML = '<p>Nenhum modelo encontrado.</p>';
                                                                                                                  return;
                                                                                                                    }

                                                                                                                      lista.forEach(item => {
                                                                                                                          const card = document.createElement('div');
                                                                                                                              card.className = 'product-card';
                                                                                                                                  card.innerHTML = `
                                                                                                                                        <img src="${item.imagem}" alt="${item.descricao}">
                                                                                                                                              <div>
                                                                                                                                                      <div class="product-title">${item.descricao}</div>
                                                                                                                                                              <div class="rating">
                                                                                                                                                                        <i class="fa-solid fa-star"></i>
                                                                                                                                                                                  <i class="fa-solid fa-star"></i>
                                                                                                                                                                                            <i class="fa-solid fa-star"></i>
                                                                                                                                                                                                      <i class="fa-solid fa-star"></i>
                                                                                                                                                                                                                <i class="fa-solid fa-star-half-stroke"></i> (4.8)
                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                <div class="price">R$ ${item.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
                                                                                                                                                                                                                                        <div class="prime-badge"><i class="fa-solid fa-check"></i> prime É grátis</div>
                                                                                                                                                                                                                                                <p style="font-size: 12px; color: ${item.quantidade > 0 ? '#007600' : '#b12704'}; margin-bottom: 10px;">
                                                                                                                                                                                                                                                          ${item.quantidade > 0 ? `Em estoque (${item.quantidade} disponíveis)` : 'Esgotado'}
                                                                                                                                                                                                                                                                  </p>
                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                              <button class="btn-amazon-cart" onclick="adicionarAoCarrinho(${item.codigo})" ${item.quantidade === 0 ? 'disabled style="opacity:0.5"' : ''}>
                                                                                                                                                                                                                                                                                      Adicionar ao Carrinho
                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                `;
                                                                                                                                                                                                                                                                                                    gridProdutos.appendChild(card);
                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                      // 2. RENDERIZAR TABELA DE CONTROLE DE ESTOQUE
                                                                                                                                                                                                                                                                                                      function renderizarTabela(lista) {
                                                                                                                                                                                                                                                                                                        tabelaEstoque.innerHTML = '';

                                                                                                                                                                                                                                                                                                          lista.forEach(item => {
                                                                                                                                                                                                                                                                                                              const tr = document.createElement('tr');
                                                                                                                                                                                                                                                                                                                  tr.innerHTML = `
                                                                                                                                                                                                                                                                                                                        <td>#${item.codigo}</td>
                                                                                                                                                                                                                                                                                                                              <td><img src="${item.imagem}" class="table-img"></td>
                                                                                                                                                                                                                                                                                                                                    <td><strong>${item.descricao}</strong></td>
                                                                                                                                                                                                                                                                                                                                          <td>${item.quantidade} un.</td>
                                                                                                                                                                                                                                                                                                                                                <td>R$ ${item.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                                                                                                                                                                                                                                                                                                                                                      <td>
                                                                                                                                                                                                                                                                                                                                                              <button class="btn-action" onclick="alterarValor(${item.codigo})"><i class="fa-solid fa-pen"></i> Alterar Preço</button>
                                                                                                                                                                                                                                                                                                                                                                      <button class="btn-action" onclick="alterarQuantidade(${item.codigo})"><i class="fa-solid fa-boxes-stack"></i> Alterar Qtd</button>
                                                                                                                                                                                                                                                                                                                                                                            </td>
                                                                                                                                                                                                                                                                                                                                                                                `;
                                                                                                                                                                                                                                                                                                                                                                                    tabelaEstoque.appendChild(tr);
                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                      // 3. CADASTRAR NOVO PRODUTO NO ESTOQUE
                                                                                                                                                                                                                                                                                                                                                                                      form.addEventListener('submit', (e) => {
                                                                                                                                                                                                                                                                                                                                                                                        e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                          const codigo = parseInt(document.getElementById('codigo').value);
                                                                                                                                                                                                                                                                                                                                                                                            const descricao = document.getElementById('descricao').value;
                                                                                                                                                                                                                                                                                                                                                                                              const quantidade = parseInt(document.getElementById('quantidade').value);
                                                                                                                                                                                                                                                                                                                                                                                                const valor = parseFloat(document.getElementById('valor').value);
                                                                                                                                                                                                                                                                                                                                                                                                  const imagem = document.getElementById('imagem').value;

                                                                                                                                                                                                                                                                                                                                                                                                    const jaExiste = estoque.some(item => item.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                      if (jaExiste) {
                                                                                                                                                                                                                                                                                                                                                                                                          alert(`Erro: O código #${codigo} já está cadastrado.`);
                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                  estoque.push({ codigo, descricao, quantidade, valor, imagem });
                                                                                                                                                                                                                                                                                                                                                                                                                    form.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarInterface();
                                                                                                                                                                                                                                                                                                                                                                                                                        alert('Chopper cadastrada com sucesso no catálogo!');
                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                        // 4. ALTERAR VALOR DO PRODUTO
                                                                                                                                                                                                                                                                                                                                                                                                                        function alterarValor(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                          const item = estoque.find(prod => prod.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                            if (!item) return;

                                                                                                                                                                                                                                                                                                                                                                                                                              const novoValor = prompt(`Informe o novo valor para "${item.descricao}":`, item.valor);
                                                                                                                                                                                                                                                                                                                                                                                                                                if (novoValor !== null && !isNaN(novoValor) && parseFloat(novoValor) >= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    item.valor = parseFloat(novoValor);
                                                                                                                                                                                                                                                                                                                                                                                                                                        atualizarInterface();
                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                          // 5. ALTERAR QUANTIDADE DO PRODUTO
                                                                                                                                                                                                                                                                                                                                                                                                                                          function alterarQuantidade(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            const item = estoque.find(prod => prod.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!item) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                const novaQtd = prompt(`Informe a nova quantidade para "${item.descricao}":`, item.quantidade);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (novaQtd !== null && !isNaN(novaQtd) && parseInt(novaQtd) >= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      item.quantidade = parseInt(novaQtd);
                                                                                                                                                                                                                                                                                                                                                                                                                                                          atualizarInterface();
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 6. BUSCA DINÂMICA
                                                                                                                                                                                                                                                                                                                                                                                                                                                            function filtrarProdutos() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              const termo = document.getElementById('input-busca').value.toLowerCase();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const filtrados = estoque.filter(item => 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item.descricao.toLowerCase().includes(termo) || 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item.codigo.toString().includes(termo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            renderizarCatalogo(filtrados);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 7. GESTÃO DO CARRINHO DE COMPRAS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function adicionarAoCarrinho(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const produto = estoque.find(p => p.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!produto || produto.quantidade <= 0) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const itemNoCarrinho = carrinho.find(item => item.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (itemNoCarrinho) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (itemNoCarrinho.qtdSelecionada < produto.quantidade) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              itemNoCarrinho.qtdSelecionada++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert('Quantidade máxima em estoque atingida para este veículo.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        carrinho.push({ ...produto, qtdSelecionada: 1 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarCarrinhoModal();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              abrirCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function alterarQtdCarrinho(codigo, delta) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const itemNoCarrinho = carrinho.find(item => item.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const produtoEstoque = estoque.find(p => p.codigo === codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!itemNoCarrinho) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const novaQtd = itemNoCarrinho.qtdSelecionada + delta;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (novaQtd <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            removerDoCarrinho(codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (novaQtd <= produtoEstoque.quantidade) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  itemNoCarrinho.qtdSelecionada = novaQtd;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarCarrinhoModal();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert('Limite em estoque atingido.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function removerDoCarrinho(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carrinho = carrinho.filter(item => item.codigo !== codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  atualizarCarrinhoModal();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function limparCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    carrinho = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarCarrinhoModal();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function atualizarCarrinhoModal() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const totalItens = carrinho.reduce((sum, item) => sum + item.qtdSelecionada, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          carrinhoQtd.textContent = totalItens;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            itensCarrinhoContainer.innerHTML = '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (carrinho.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  itensCarrinhoContainer.innerHTML = '<p style="text-align: center; color: #777; padding: 20px;">Seu carrinho está vazio.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cartTotalValor.textContent = 'R$ 0,00';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let valorTotal = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carrinho.forEach(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const subtotal = item.valor * item.qtdSelecionada;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        valorTotal += subtotal;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const cartRow = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cartRow.className = 'cart-item';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartRow.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <img src="${item.imagem}" alt="${item.descricao}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="cart-item-details">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="cart-item-title">${item.descricao}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="cart-item-price">R$ ${item.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span class="btn-remove" onclick="removerDoCarrinho(${item.codigo})">Excluir</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="cart-item-qty">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="btn-qty" onclick="alterarQtdCarrinho(${item.codigo}, -1)">-</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>${item.qtdSelecionada}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="btn-qty" onclick="alterarQtdCarrinho(${item.codigo}, 1)">+</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          itensCarrinhoContainer.appendChild(cartRow);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cartTotalValor.textContent = `R$ ${valorTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // CONTROLE DE ABERTURA E FECHAMENTO DO MODAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function abrirCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                modalCarrinho.style.display = 'flex';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function fecharCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  modalCarrinho.style.display = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function finalizarCompra() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (carrinho.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert('Seu carrinho está vazio!');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carrinho.forEach(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produtoEstoque = estoque.find(p => p.codigo === item.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (produtoEstoque) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              produtoEstoque.quantidade -= item.qtdSelecionada;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      alert('Compra realizada com sucesso! Parabéns pela sua nova Chopper.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        carrinho = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fecharCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarInterface();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // FECHAR MODAL AO CLICAR FORA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            window.onclick = function(event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (event.target === modalCarrinho) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fecharCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // INICIALIZAÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarInterface();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    